package com.example.onlinevideo; import android.net.Uri; import android.os.Bundle; import android.view.View; import android.widget.MediaController; import android.widget.VideoView; import androidx.appcompat.app.AppCompatActivity; public class MainActivity extends AppCompatActivity { VideoView vvVideo; @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);vvVideo=findViewById(R.id.vvVideo);MediaController c=new MediaController(this);c.setAnchorView(vvVideo);vvVideo.setMediaController(c);} public void playVideo(View v){vvVideo.setVideoURI(Uri.parse("https://www.w3schools.com/html/mov_bbb.mp4"));vvVideo.start();}}
